#!/usr/bin/env node
// V1 helper for file-based hypothesis/evidence tracking inside workspace.
// Usage:
//   node .v1/helpers.js add-hypothesis '{"description":"...","evidence":["file:line"],"confidence":0.8,"files":["src/foo.ts"]}'
//   node .v1/helpers.js select-hypothesis <id>
//   node .v1/helpers.js add-evidence '{"type":"file_inspection","description":"...","source":"src/foo.ts","result":"supports"}'
//   node .v1/helpers.js add-file-inspected src/foo.ts
//   node .v1/helpers.js add-command '{"command":"npm test","exitCode":0,"stdout":"..."}'
//   node .v1/helpers.js add-verification '{"method":"vitest","command":"vitest run","passed":true,"output":"..."}'
//   node .v1/helpers.js status
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { randomUUID } from "node:crypto";

const STATE_PATH = join(process.cwd(), ".v1/state.json");

function load() {
  if (!existsSync(STATE_PATH)) {
    console.error("No .v1/state.json found at", STATE_PATH);
    process.exit(1);
  }
  const raw = readFileSync(STATE_PATH, "utf-8");
  return JSON.parse(raw);
}
function save(s) {
  mkdirSync(dirname(STATE_PATH), { recursive: true });
  writeFileSync(STATE_PATH, JSON.stringify(s, null, 2), "utf-8");
}

const cmd = process.argv[2];
if (!cmd || cmd === "help" || cmd === "--help") {
  console.log("Usage: node .v1/helpers.js <add-hypothesis|select-hypothesis|add-evidence|add-file-inspected|add-command|add-verification|status>");
  process.exit(0);
}
if (cmd === "status") {
  const s = load();
  console.log(JSON.stringify(s, null, 2));
  process.exit(0);
}
if (cmd === "add-hypothesis") {
  const arg = process.argv[3];
  if (!arg) { console.error("need JSON arg"); process.exit(1); }
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg, evidence: [] }; }
  const s = load();
  const h = {
    id: payload.id ?? `hyp-${randomUUID().slice(0, 8)}`,
    description: payload.description ?? "hypothesis",
    evidence: payload.evidence ?? [],
    confidence: payload.confidence ?? 0.5,
    status: payload.status ?? "active",
    files: payload.files,
  };
  s.hypotheses = s.hypotheses ?? [];
  s.hypotheses.push(h);
  // also push evidence entry for diagnosis
  s.evidence = s.evidence ?? [];
  s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: "other", description: `Hypothesis: ${h.description}`, source: h.files?.[0], result: "neutral", timestamp: new Date().toISOString(), phase: s.phase });
  save(s);
  console.log(h.id);
  process.exit(0);
}
if (cmd === "select-hypothesis") {
  const id = process.argv[3];
  if (!id) { console.error("need id"); process.exit(1); }
  const s = load();
  let found = false;
  for (const hyp of s.hypotheses) {
    if (hyp.id === id) { hyp.status = "selected"; s.selectedHypothesis = id; found = true; }
    else if (hyp.status === "selected") hyp.status = "active";
  }
  if (!found) { console.error("hypothesis not found", id); process.exit(1); }
  save(s);
  console.log("selected", id);
  process.exit(0);
}
if (cmd === "add-evidence") {
  const arg = process.argv[3];
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg }; }
  const s = load();
  s.evidence = s.evidence ?? [];
  s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: payload.type ?? "other", description: payload.description ?? arg, source: payload.source, result: payload.result ?? "neutral", timestamp: new Date().toISOString(), phase: payload.phase ?? s.phase });
  save(s);
  console.log("evidence added");
  process.exit(0);
}
if (cmd === "add-file-inspected") {
  const p = process.argv[3];
  const s = load();
  s.filesInspected = s.filesInspected ?? [];
  if (!s.filesInspected.includes(p)) s.filesInspected.push(p);
  save(s);
  console.log("file recorded", p);
  process.exit(0);
}
if (cmd === "add-command") {
  // raw json {command, exitCode, stdout, stderr, durationMs}
  const arg = process.argv.slice(3).join(" ");
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { command: arg }; }
  const s = load();
  s.commandsExecuted = s.commandsExecuted ?? [];
  s.commandsExecuted.push({ command: payload.command ?? arg, exitCode: payload.exitCode ?? null, stdout: payload.stdout ?? "", stderr: payload.stderr ?? "", durationMs: payload.durationMs ?? 0, phase: s.phase, timestamp: new Date().toISOString() });
  save(s);
  console.log("command recorded");
  process.exit(0);
}
if (cmd === "add-verification") {
  const arg = process.argv.slice(3).join(" ");
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { method: arg, output: arg }; }
  const s = load();
  s.verificationAttempts = s.verificationAttempts ?? [];
  s.verificationAttempts.push({ id: `ver-${randomUUID().slice(0, 8)}`, iteration: s.iteration, method: payload.method ?? "manual", command: payload.command, passed: payload.passed ?? null, output: payload.output ?? JSON.stringify(payload), timestamp: new Date().toISOString(), phase: s.phase });
  if (payload.passed !== undefined || payload.output) {
    s.evidence = s.evidence ?? [];
    s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: payload.type ?? "test_result", description: `Verification: ${payload.method ?? payload.command ?? "check"}`, source: payload.command, result: payload.passed ? "supports" : payload.passed === false ? "contradicts" : "neutral", timestamp: new Date().toISOString(), phase: s.phase });
  }
  save(s);
  console.log("verification recorded");
  process.exit(0);
}
console.error("unknown command", cmd);
process.exit(1);

{
  "name": "money-utils",
  "version": "1.0.0",
  "description": "Currency and money utilities for Frontier Verifier benchmark",
  "type": "module",
  "license": "MIT",
  "main": "src/index.ts",
  "scripts": {
    "test": "vitest run",
    "check-types": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/bun": "latest"
  }
}

export interface Money {
  amount: number;
  currency: string;
}

export function createMoney(amount: number, currency: string): Money {
  if (typeof amount !== "number" || isNaN(amount)) throw new Error("Invalid amount");
  if (typeof currency !== "string" || currency.length !== 3) throw new Error(`Invalid currency: ${currency}`);
  return { amount: roundToCents(amount), currency: currency.toUpperCase() };
}

export function roundToCents(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

export function formatMoney(money: Money): string {
  const rounded = roundToCents(money.amount);
  return `${rounded.toFixed(2)} ${money.currency}`;
}

export function parseMoney(input: string): Money {
  if (typeof input !== "string") throw new Error("Input must be string");
  const trimmed = input.trim();
  const currencyMatch = trimmed.match(/\b([A-Z]{3})\b/i);
  if (!currencyMatch) throw new Error(`Could not parse currency from: ${input}`);
  const currency = currencyMatch[1]!.toUpperCase();
  let numericPart = trimmed.replace(new RegExp(currency, "i"), "").replace(/[$€£¥]/g, "").trim();
  numericPart = numericPart.replace(/,/g, "").trim();
  if (numericPart === "" || numericPart === "." || numericPart === "-") {
    throw new Error(`Could not parse amount from: ${input}`);
  }
  const amount = parseFloat(numericPart);
  if (isNaN(amount)) throw new Error(`Could not parse amount from: ${input}`);
  return { amount: roundToCents(amount), currency };
}

export function add(a: Money, b: Money): Money {
  // BUG: missing currency check
  return { amount: roundToCents(a.amount + b.amount), currency: a.currency };
}

export function subtract(a: Money, b: Money): Money {
  // BUG: also missing check for symmetry
  return { amount: roundToCents(a.amount - b.amount), currency: a.currency };
}

export function multiply(money: Money, factor: number): Money {
  if (typeof factor !== "number" || isNaN(factor)) throw new Error("Invalid factor");
  return { amount: roundToCents(money.amount * factor), currency: money.currency };
}

export function convertCurrency(money: Money, targetCurrency: string, rates: Record<string, number>): Money {
  const target = targetCurrency.toUpperCase();
  if (money.currency === target) return { ...money };
  const key = `${money.currency}_${target}`;
  const rate = rates[key];
  if (rate === undefined) throw new Error(`Missing exchange rate: ${key}`);
  const converted = money.amount * rate;
  return { amount: roundToCents(converted), currency: target };
}

import { describe, test, expect } from "vitest";
import { createMoney, formatMoney, parseMoney, add, subtract, multiply, convertCurrency, roundToCents } from "../src/money.ts";

describe("money-utils", () => {
  test("roundToCents rounds half-up", () => {
    expect(roundToCents(1.005)).toBe(1.01);
    expect(roundToCents(1.004)).toBe(1.0);
    expect(roundToCents(2.675)).toBe(2.68);
  });

  test("formatMoney formats to 2 decimals", () => {
    expect(formatMoney({ amount: 10, currency: "USD" })).toBe("10.00 USD");
    expect(formatMoney({ amount: 10.5, currency: "EUR" })).toBe("10.50 EUR");
    expect(formatMoney({ amount: 1.005, currency: "USD" })).toBe("1.01 USD");
  });

  test("parseMoney handles comma-separated", () => {
    expect(parseMoney("1,000.00 USD")).toEqual({ amount: 1000, currency: "USD" });
    expect(parseMoney("$1,234.56 USD")).toEqual({ amount: 1234.56, currency: "USD" });
    expect(parseMoney("USD 2,500.99")).toEqual({ amount: 2500.99, currency: "USD" });
  });

  test("parseMoney handles simple amounts", () => {
    expect(parseMoney("100 USD")).toEqual({ amount: 100, currency: "USD" });
    expect(parseMoney("99.99 EUR")).toEqual({ amount: 99.99, currency: "EUR" });
  });

  test("add validates currency mismatch", () => {
    const a = createMoney(10, "USD");
    const b = createMoney(5, "EUR");
    expect(() => add(a, b)).toThrow(/Currency mismatch/);
    expect(add(a, createMoney(5, "USD"))).toEqual({ amount: 15, currency: "USD" });
  });

  test("subtract validates currency", () => {
    expect(() => subtract(createMoney(10, "USD"), createMoney(5, "EUR"))).toThrow();
  });

  test("multiply", () => {
    expect(multiply(createMoney(10, "USD"), 2.5)).toEqual({ amount: 25, currency: "USD" });
  });

  test("convertCurrency precision", () => {
    const m = createMoney(100, "USD");
    const rates = { "USD_EUR": 0.9234, "EUR_USD": 1.083 };
    expect(convertCurrency(m, "EUR", rates)).toEqual({ amount: 92.34, currency: "EUR" });
    // large amount: 999999.99 * 0.9234 = 923399.990766 -> 923399.99 after rounding
    const large = createMoney(999999.99, "USD");
    expect(convertCurrency(large, "EUR", rates).amount).toBe(923399.99);
    // same currency no conversion
    expect(convertCurrency(m, "USD", rates)).toEqual(m);
    expect(convertCurrency(m, "usd", rates)).toEqual(m);
  });

  test("convertCurrency throws missing rate", () => {
    expect(() => convertCurrency(createMoney(10, "USD"), "JPY", {})).toThrow(/Missing exchange rate/);
  });

  test("createMoney validates", () => {
    expect(() => createMoney(NaN, "USD")).toThrow();
    expect(() => createMoney(10, "US")).toThrow();
  });
});

