// Minimal reproduction of the currency mismatch bug
// This script demonstrates that add() and subtract() don't throw on currency mismatch

import { createMoney, add, subtract, multiply } from '../src/money.ts';

console.log('=== Currency Mismatch Bug Reproduction ===\n');

// Test 1: add() should throw on currency mismatch
console.log('Test 1: add() with different currencies');
const usd10 = createMoney(10, 'USD');
const eur5 = createMoney(5, 'EUR');

try {
  const result = add(usd10, eur5);
  console.log('BUG: add() did NOT throw on currency mismatch');
  console.log('  Result:', result);
  console.log('  Expected: Error("Currency mismatch")');
  console.log('  Status: FAIL\n');
} catch (e: any) {
  console.log('PASS: add() threw error:', e.message);
  console.log('  Status: PASS\n');
}

// Test 2: subtract() should throw on currency mismatch
console.log('Test 2: subtract() with different currencies');
try {
  const result = subtract(usd10, eur5);
  console.log('BUG: subtract() did NOT throw on currency mismatch');
  console.log('  Result:', result);
  console.log('  Expected: Error("Currency mismatch")');
  console.log('  Status: FAIL\n');
} catch (e: any) {
  console.log('PASS: subtract() threw error:', e.message);
  console.log('  Status: PASS\n');
}

// Test 3: add() should work with same currency (case-insensitive)
console.log('Test 3: add() with same currency (case-insensitive)');
try {
  const result = add(usd10, createMoney(5, 'usd'));
  console.log('Result:', result);
  console.log('Expected: { amount: 15, currency: "USD" }');
